import React from "react";
import "./DoctorDashboard.css";

const DoctorDashboard = () => {
  const doctorName = localStorage.getItem("name") || "Dr. Smith";

  return (
    <div className="doctor-dashboard-container">
      <header className="doctor-header">
        <h1>Welcome, {doctorName}</h1>
        <p>Empowering better care with MediVault</p>
      </header>

      <div className="doctor-main">
        <div className="card">
          <h3>View Appointments</h3>
          <p>Check upcoming patient schedules</p>
        </div>
        <div className="card">
          <h3>Upload Prescriptions</h3>
          <p>Directly add digital prescriptions to patient vaults</p>
        </div>
        <div className="card">
          <h3>Patient History</h3>
          <p>Access previous visits, diagnostics & treatments</p>
        </div>
        <div className="card">
          <h3>Connect with Patients</h3>
          <p>Secure chat & follow-up reminders (future scope)</p>
        </div>
      </div>
    </div>
  );
};

export default DoctorDashboard;
